package net.civeira.phylax.feature.notification.smtpoutboundconfig.application.usecase.update;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.feature.identity.tenant.domain.TenantReference;
import net.civeira.phylax.feature.notification.smtpoutboundconfig.domain.SmtpOutboundConfigChangeSet;

class SmtpOutboundConfigUpdateInputUnitTest {

  /**
   * @autogenerated UpdateInputGenerator
   */
  @Test
  @DisplayName("Test the smtp outbound config input values are kept when converted to a change set and back")
  void test_smtp_outbound_config_update_input_change_set_round_trip() {
    SmtpOutboundConfigUpdateInput input =
        SmtpOutboundConfigUpdateInput.builder().uid("one").tenant(TenantReference.of("one"))
            .host("one").port(1).login("one").senderName("one").senderEmail("one").timeout(1)
            .useTls(true).maxRetries(1).retryDelay(1).rateLimit(1).version(1).build();
    SmtpOutboundConfigChangeSet changes = input.toChangeSet();
    Assertions.assertNotNull(changes, "A change set must be created");
    SmtpOutboundConfigUpdateInput copy = SmtpOutboundConfigUpdateInput.fromChangeSet(changes);
    Assertions.assertTrue(input.getUid().isPresent(), "uid must be assigned by the builder");
    Assertions.assertEquals(input.getUid(), copy.getUid(),
        "uid must survive the change set round trip");
    Assertions.assertTrue(input.getTenant().isPresent(), "tenant must be assigned by the builder");
    Assertions.assertEquals(input.getTenant(), copy.getTenant(),
        "tenant must survive the change set round trip");
    Assertions.assertTrue(input.getHost().isPresent(), "host must be assigned by the builder");
    Assertions.assertEquals(input.getHost(), copy.getHost(),
        "host must survive the change set round trip");
    Assertions.assertTrue(input.getPort().isPresent(), "port must be assigned by the builder");
    Assertions.assertEquals(input.getPort(), copy.getPort(),
        "port must survive the change set round trip");
    Assertions.assertTrue(input.getLogin().isPresent(), "login must be assigned by the builder");
    Assertions.assertEquals(input.getLogin(), copy.getLogin(),
        "login must survive the change set round trip");
    Assertions.assertTrue(input.getSenderName().isPresent(),
        "senderName must be assigned by the builder");
    Assertions.assertEquals(input.getSenderName(), copy.getSenderName(),
        "senderName must survive the change set round trip");
    Assertions.assertTrue(input.getSenderEmail().isPresent(),
        "senderEmail must be assigned by the builder");
    Assertions.assertEquals(input.getSenderEmail(), copy.getSenderEmail(),
        "senderEmail must survive the change set round trip");
    Assertions.assertTrue(input.getTimeout().isPresent(),
        "timeout must be assigned by the builder");
    Assertions.assertEquals(input.getTimeout(), copy.getTimeout(),
        "timeout must survive the change set round trip");
    Assertions.assertTrue(input.getUseTls().isPresent(), "useTls must be assigned by the builder");
    Assertions.assertEquals(input.getUseTls(), copy.getUseTls(),
        "useTls must survive the change set round trip");
    Assertions.assertTrue(input.getMaxRetries().isPresent(),
        "maxRetries must be assigned by the builder");
    Assertions.assertEquals(input.getMaxRetries(), copy.getMaxRetries(),
        "maxRetries must survive the change set round trip");
    Assertions.assertTrue(input.getRetryDelay().isPresent(),
        "retryDelay must be assigned by the builder");
    Assertions.assertEquals(input.getRetryDelay(), copy.getRetryDelay(),
        "retryDelay must survive the change set round trip");
    Assertions.assertTrue(input.getRateLimit().isPresent(),
        "rateLimit must be assigned by the builder");
    Assertions.assertEquals(input.getRateLimit(), copy.getRateLimit(),
        "rateLimit must survive the change set round trip");
    Assertions.assertTrue(input.getVersion().isPresent(),
        "version must be assigned by the builder");
    Assertions.assertEquals(input.getVersion(), copy.getVersion(),
        "version must survive the change set round trip");
  }

  /**
   * @autogenerated UpdateInputGenerator
   */
  @Test
  @DisplayName("Test the smtp outbound config input builder can generate a new identifier")
  void test_smtp_outbound_config_update_input_new_uid() {
    SmtpOutboundConfigUpdateInput input = SmtpOutboundConfigUpdateInput.builder().newUid().build();
    Assertions.assertTrue(input.getUid().isPresent(), "A new uid must be generated");
    Assertions.assertTrue(input.getVersion().isPresent(), "The initial version must be assigned");
    Assertions.assertNotEquals(input.getUid(),
        SmtpOutboundConfigUpdateInput.builder().newUid().build().getUid(),
        "Each new uid must be different");
  }

  /**
   * @autogenerated UpdateInputGenerator
   */
  @Test
  @DisplayName("Test the smtp outbound config input starts empty and the setters assign values")
  void test_smtp_outbound_config_update_input_setters() {
    SmtpOutboundConfigUpdateInput empty = SmtpOutboundConfigUpdateInput.builder().build();
    Assertions.assertTrue(empty.getUid().isEmpty(), "uid must be empty by default");
    Assertions.assertSame(empty, empty.setUid("one"), "The setter must allow a flow code");
    Assertions.assertTrue(empty.getUid().isPresent(), "uid must be assigned by the setter");
    Assertions.assertTrue(empty.getTenant().isEmpty(), "tenant must be empty by default");
    Assertions.assertSame(empty, empty.setTenant(TenantReference.of("one")),
        "The setter must allow a flow code");
    Assertions.assertTrue(empty.getTenant().isPresent(), "tenant must be assigned by the setter");
    Assertions.assertTrue(empty.getHost().isEmpty(), "host must be empty by default");
    Assertions.assertSame(empty, empty.setHost("one"), "The setter must allow a flow code");
    Assertions.assertTrue(empty.getHost().isPresent(), "host must be assigned by the setter");
    Assertions.assertTrue(empty.getPort().isEmpty(), "port must be empty by default");
    Assertions.assertSame(empty, empty.setPort(1), "The setter must allow a flow code");
    Assertions.assertTrue(empty.getPort().isPresent(), "port must be assigned by the setter");
    Assertions.assertTrue(empty.getLogin().isEmpty(), "login must be empty by default");
    Assertions.assertSame(empty, empty.setLogin("one"), "The setter must allow a flow code");
    Assertions.assertTrue(empty.getLogin().isPresent(), "login must be assigned by the setter");
    Assertions.assertTrue(empty.getSenderName().isEmpty(), "senderName must be empty by default");
    Assertions.assertSame(empty, empty.setSenderName("one"), "The setter must allow a flow code");
    Assertions.assertTrue(empty.getSenderName().isPresent(),
        "senderName must be assigned by the setter");
    Assertions.assertTrue(empty.getSenderEmail().isEmpty(), "senderEmail must be empty by default");
    Assertions.assertSame(empty, empty.setSenderEmail("one"), "The setter must allow a flow code");
    Assertions.assertTrue(empty.getSenderEmail().isPresent(),
        "senderEmail must be assigned by the setter");
    Assertions.assertTrue(empty.getTimeout().isEmpty(), "timeout must be empty by default");
    Assertions.assertSame(empty, empty.setTimeout(1), "The setter must allow a flow code");
    Assertions.assertTrue(empty.getTimeout().isPresent(), "timeout must be assigned by the setter");
    Assertions.assertTrue(empty.getUseTls().isEmpty(), "useTls must be empty by default");
    Assertions.assertSame(empty, empty.setUseTls(true), "The setter must allow a flow code");
    Assertions.assertTrue(empty.getUseTls().isPresent(), "useTls must be assigned by the setter");
    Assertions.assertTrue(empty.getMaxRetries().isEmpty(), "maxRetries must be empty by default");
    Assertions.assertSame(empty, empty.setMaxRetries(1), "The setter must allow a flow code");
    Assertions.assertTrue(empty.getMaxRetries().isPresent(),
        "maxRetries must be assigned by the setter");
    Assertions.assertTrue(empty.getRetryDelay().isEmpty(), "retryDelay must be empty by default");
    Assertions.assertSame(empty, empty.setRetryDelay(1), "The setter must allow a flow code");
    Assertions.assertTrue(empty.getRetryDelay().isPresent(),
        "retryDelay must be assigned by the setter");
    Assertions.assertTrue(empty.getRateLimit().isEmpty(), "rateLimit must be empty by default");
    Assertions.assertSame(empty, empty.setRateLimit(1), "The setter must allow a flow code");
    Assertions.assertTrue(empty.getRateLimit().isPresent(),
        "rateLimit must be assigned by the setter");
    Assertions.assertTrue(empty.getVersion().isEmpty(), "version must be empty by default");
    Assertions.assertSame(empty, empty.setVersion(1), "The setter must allow a flow code");
    Assertions.assertTrue(empty.getVersion().isPresent(), "version must be assigned by the setter");
    Assertions.assertNotNull(empty.toChangeSet(), "A change set must be created");
  }
}
